<!DOCTYPE html><html lang="de"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rechnungsanschrift · {{ $kunde->strName }}</title><style>*{box-sizing:border-box}body{margin:0;font:14px Segoe UI,Arial;background:#f4f6f8;color:#1f2937}.page{max-width:1050px;margin:auto;padding:32px}.card{background:white;border-radius:12px;box-shadow:0 2px 8px #0001;padding:24px}a{color:#0369a1;text-decoration:none}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.field label{display:block;color:#64748b;margin-bottom:5px}.field input{width:100%;padding:10px;border:1px solid #ccd2d8;border-radius:7px}.checks{display:flex;gap:22px;margin-top:20px}.actions{display:flex;gap:10px;margin-top:20px}.button,button{padding:10px 16px;border:0;border-radius:8px;background:#0069c2;color:white;text-decoration:none}.secondary{background:#e5e7eb;color:#111827}</style></head><body><div class="page"><a href="{{ route('kunden.rechnungsanschriften.index',$kunde->intID) }}">← Rechnungsanschriften</a><h1>{{ $anschrift->exists ? 'Rechnungsanschrift bearbeiten' : 'Neue Rechnungsanschrift' }}</h1><div class="card"><form method="POST" action="{{ $anschrift->exists ? route('kunden.rechnungsanschriften.update',[$kunde->intID,$anschrift->intID]) : route('kunden.rechnungsanschriften.store',$kunde->intID) }}">@csrf @if($anschrift->exists) @method('PUT') @endif<div class="grid">@foreach(['strName'=>'Name','strZuHaenden'=>'Zu Händen','strStrasse'=>'Straße','strPLZ'=>'PLZ','strOrt'=>'Ort','strEmail'=>'E-Mail','strUStIdNr'=>'USt-IdNr.','strKundenreferenz'=>'Kundenreferenz','strInhaber'=>'Kontoinhaber','strIBAN'=>'IBAN','strBIC'=>'BIC','strKontoNr'=>'Kontonummer','strBLZ'=>'BLZ','strInstitut'=>'Institut','strLieferantenId'=>'Lieferanten-ID','strLeitwegId'=>'Leitweg-ID'] as $name=>$label)<div class="field"><label>{{ $label }}</label><input name="{{ $name }}" value="{{ old($name,$anschrift->$name) }}" @if($name==='strName') required @endif></div>@endforeach</di